#!/usr/bin/env bash
# Testnet only: hands a relayer account created on this host to the owner after scripts/deploy.sh succeeded.
#   1. adds the owner's public key as a full-access key on RELAYER_ID
#   2. gate (a): that key is FullAccess on chain, else stop before any delete
#   3. deletes the relayer's autogenerated full-access key (it signs its own deletion)
#   4. gate (b): the key list is exactly { owner key: FullAccess, R: claim-only on CONTRACT_ID },
#      else stop and leave every local file in place
#   5. shreds the relayer's local key files (and the escrow's dead ones, if the escrow has no keys)
#
# Required env:
#   CONTRACT_ID, OWNER_ID, RELAYER_ID
#   RELAYER_PUBKEY   R, the relayer's claim-only public key (ed25519:...), already on RELAYER_ID
# Optional env:
#   NETWORK          testnet (default) or mainnet
#   OWNER_PK         the owner's public key; default: public_key of ~/.near-credentials/$NETWORK/$OWNER_ID.json
#   RPC              default: FastNEAR for NETWORK
#   DRY_RUN=1        run the read-only checks, print the writes and shreds instead of running them
set -euo pipefail

NETWORK=${NETWORK:-testnet}
case $NETWORK in
  testnet) RPC=${RPC:-https://test.rpc.fastnear.com} ;;
  mainnet) RPC=${RPC:-https://free.rpc.fastnear.com} ;;
  *) echo "NETWORK must be testnet or mainnet" >&2; exit 64 ;;
esac
# Mainnet never has a relayer full-access key on this host to hand over: deploy.sh's owner kit creates the
# relayer on the owner's machine, and its full-access key never leaves that machine's key store.
[[ $NETWORK != mainnet ]] || { echo "relayer-handover: not used on mainnet (docs/deploy/mainnet.md, owner kit step 2)" >&2; exit 64; }
: "${CONTRACT_ID:?set CONTRACT_ID}" "${OWNER_ID:?set OWNER_ID}" "${RELAYER_ID:?set RELAYER_ID}" "${RELAYER_PUBKEY:?set RELAYER_PUBKEY (R)}"
creds=$HOME/.near-credentials/$NETWORK
PK_RE='^ed25519:[1-9A-HJ-NP-Za-km-z]{32,44}$'
die() { echo "relayer-handover: STOP: $*" >&2; exit 1; }
run() { if [[ ${DRY_RUN:-} == 1 ]]; then printf '+'; printf ' %q' "$@"; echo; else "$@"; fi; }

rpc_query() { # rpc_query <jq filter for params> [args...]
  local params; params=$(jq -nc "$@")
  curl -sSf "$RPC" -H 'content-type: application/json' \
    -d "$(jq -nc --argjson p "$params" '{jsonrpc:"2.0",id:1,method:"query",params:$p}')"
}
permission() { # permission <account> <public key>: the permission JSON, or empty if the key is absent
  rpc_query --arg a "$1" --arg k "$2" '{request_type:"view_access_key",finality:"final",account_id:$a,public_key:$k}' |
    jq -c '.result.permission // empty'
}
key_list() { rpc_query --arg a "$1" '{request_type:"view_access_key_list",finality:"final",account_id:$a}' | jq -c '.result.keys'; }
is_claim_only() { jq -e --arg c "$CONTRACT_ID" '.FunctionCall.receiver_id == $c and .FunctionCall.method_names == ["claim"]' >/dev/null 2>&1; }
retry() { local i; for i in 1 2 3; do "$@" && return 0; [[ $i == 3 ]] || sleep 2; done; return 1; } # RPC lag

# --- preflight: read-only, nothing written yet ---
[[ $RELAYER_PUBKEY =~ $PK_RE ]] || die "RELAYER_PUBKEY is not an ed25519 public key"
if [[ -z ${OWNER_PK:-} ]]; then
  [[ -f $creds/$OWNER_ID.json ]] || die "no $creds/$OWNER_ID.json (import the owner key, or set OWNER_PK)"
  OWNER_PK=$(jq -r .public_key "$creds/$OWNER_ID.json")
fi
[[ $OWNER_PK =~ $PK_RE ]] || die "owner public key '$OWNER_PK' is not an ed25519 public key"
# Also catches a typo in an OWNER_PK override or a stale credentials file: the key must be the owner's.
[[ $(permission "$OWNER_ID" "$OWNER_PK") == '"FullAccess"' ]] || die "$OWNER_PK is not a full-access key of $OWNER_ID"
final_ok() {
  key_list "$RELAYER_ID" | jq -e --arg o "$OWNER_PK" --arg r "$RELAYER_PUBKEY" --arg c "$CONTRACT_ID" '
    length == 2
    and any(.[]; .public_key == $o and .access_key.permission == "FullAccess")
    and any(.[]; .public_key == $r and .access_key.permission.FunctionCall.receiver_id == $c
                 and .access_key.permission.FunctionCall.method_names == ["claim"])' >/dev/null
}
[[ -f $creds/$RELAYER_ID.json ]] || die "no $creds/$RELAYER_ID.json: nothing to hand over (already done? check the key list)"
RELAYER_FA=$(jq -r .public_key "$creds/$RELAYER_ID.json")
[[ $RELAYER_FA =~ $PK_RE ]] || die "relayer full-access key in $creds/$RELAYER_ID.json is malformed"
[[ $RELAYER_FA != "$OWNER_PK" && $RELAYER_FA != "$RELAYER_PUBKEY" && $OWNER_PK != "$RELAYER_PUBKEY" ]] ||
  die "owner key, relayer full-access key and R must be three different keys"
permission "$RELAYER_ID" "$RELAYER_PUBKEY" | is_claim_only ||
  die "R is not a claim-only key for $CONTRACT_ID on $RELAYER_ID: run deploy.sh (step 3) first"
handed_over=""
if [[ $(permission "$RELAYER_ID" "$RELAYER_FA") != '"FullAccess"' ]]; then
  # A rerun after a successful delete (e.g. gate (b) saw a lagging RPC): only the files are left.
  final_ok || die "$RELAYER_FA is not a full-access key on $RELAYER_ID, so this host cannot sign for it"
  echo "already handed over: the key list is final; removing the local files only"
  handed_over=1
fi

if [[ -z $handed_over ]]; then
# --- 1 + gate (a) ---
owner_is_full() { [[ $(permission "$RELAYER_ID" "$OWNER_PK") == '"FullAccess"' ]]; }
if owner_is_full; then
  echo "owner key already full access on $RELAYER_ID"
else
  echo "== add the owner key $OWNER_PK as full access on $RELAYER_ID"
  run near account add-key "$RELAYER_ID" grant-full-access use-manually-provided-public-key "$OWNER_PK" \
    network-config "$NETWORK" sign-with-legacy-keychain send || die "add-key failed; nothing deleted"
fi
if [[ ${DRY_RUN:-} == 1 ]]; then
  echo "(dry run) gate (a): would require view_access_key($RELAYER_ID, $OWNER_PK) = FullAccess"
else
  retry owner_is_full || die "gate (a): the owner key is not FullAccess on $RELAYER_ID; nothing deleted"
fi

# --- 2 + gate (b) ---
echo "== delete the autogenerated full-access key $RELAYER_FA"
run near account delete-keys "$RELAYER_ID" public-keys "$RELAYER_FA" network-config "$NETWORK" sign-with-legacy-keychain send ||
  die "delete-keys failed; local files left in place (the owner key is already full access, so rerunning is safe)"
if [[ ${DRY_RUN:-} == 1 ]]; then
  echo "(dry run) gate (b): would require exactly { $OWNER_PK FullAccess, $RELAYER_PUBKEY claim-only on $CONTRACT_ID }"
else
  retry final_ok || die "gate (b): key list of $RELAYER_ID is $(key_list "$RELAYER_ID"); local files left in place"
fi
fi

# --- 3: local files ---
shred_account() { # the legacy keychain keeps <account>.json and <account>/<key>.json
  local a=$1
  run shred -u "$creds/$a.json"
  if [[ -d $creds/$a ]]; then
    local f; for f in "$creds/$a"/*.json; do [[ -e $f ]] && run shred -u "$f"; done
    run rmdir "$creds/$a" || echo "WARNING: $creds/$a is not empty (non-json files?); left in place" >&2
  fi
}
echo "== remove the relayer's local key files"
shred_account "$RELAYER_ID"
if [[ -f $creds/$CONTRACT_ID.json ]]; then
  if [[ $(key_list "$CONTRACT_ID") == "[]" ]]; then
    echo "== remove the escrow's local key files (the lock deleted that key on chain)"
    shred_account "$CONTRACT_ID"
  else
    echo "WARNING: $CONTRACT_ID still has access keys on chain; its local key files are kept" >&2
  fi
fi
echo "relayer $RELAYER_ID: $(key_list "$RELAYER_ID")"
